// Customer portal: turns an action sent by the browser into an API call (output 1),
// a database query (output 2) or an immediate answer to the browser (output 3).
// msg._client identifies the browser session; every answer is sent back to that session only.
const API = env.get('API_URL') || 'http://api:8000';
const p = msg.payload || {};
const base = { _client: msg._client, action: msg.topic, ctx: p };
const api = (method, path, body) => ({ ...base, method, url: API + path,
    payload: body === undefined ? '' : body, headers: body === undefined ? {} : { 'Content-Type': 'application/json' } });
const sql = (query, params) => ({ ...base, topic: query, payload: params || [] });
const fail = text => [null, null, { _client: msg._client, topic: 'error', payload: { text } }];

const id = v => { const n = Number(v); return Number.isInteger(n) && n > 0 ? n : null; };
const order = typeof p.order_name === 'string' && /^[\w\/-]{1,30}$/.test(p.order_name) ? p.order_name : null;
const customer = id(p.customer_id);
const enc = encodeURIComponent;

switch (msg.topic) {
case 'init':
    return [api('GET', '/customers/companies'), null, null];
case 'login':
    if (!customer) return fail('Choose a customer account first.');
    return [api('GET', `/customers/${customer}`),
            sql(`INSERT INTO kpi_web_traffic (user_id, ip_address, visit_date, visit_start_time, duration_minutes, click_count)
                 VALUES (?, ?, CURDATE(), NOW(), 0, 0)`, [customer, (msg._client && msg._client.socketIp) || 'unknown']), null];
case 'logout': {
    const visit = id(p.visit_id);
    if (!visit) return null;
    return [null, sql('UPDATE kpi_web_traffic SET duration_minutes = ?, click_count = ? WHERE visit_id = ?',
        [Math.min(Math.round((Number(p.minutes) || 0) * 100) / 100, 9999), Math.min(id(p.clicks) || 0, 100000), visit]), null];
}
case 'orders':
    return customer ? [api('GET', `/saleorders/by_id/${customer}`), null, null] : null;
case 'order':
    return id(p.order_id) ? [api('GET', `/saleorders/by_orderid/${id(p.order_id)}`), null, null] : null;
case 'invoices':
    return order ? [api('GET', `/accounting/invoice/by_saleorder/${enc(order)}`), null, null] : null;
case 'confirm':
    return order ? [api('PUT', `/saleorders/quotations/confirm/${enc(order)}`), null, null] : fail('No order selected.');
case 'decline':
    return order ? [api('PUT', `/saleorders/quotations/cancel/${enc(order)}`), null, null] : fail('No order selected.');
case 'set_qty': {
    const qty = Number(p.quantity);
    if (!order || !id(p.line_id) || !(qty > 0 && qty <= 100000)) return fail('Enter a quantity greater than 0.');
    return [api('PUT', `/saleorders/${enc(order)}/lines/${id(p.line_id)}`, { quantity: qty }), null, null];
}
case 'remove_line':
    return order && id(p.line_id) ? [api('DELETE', `/saleorders/${enc(order)}/lines/${id(p.line_id)}`), null, null] : fail('No line selected.');
case 'accept_date':
    return order ? [api('PUT', `/saleorders/delivery_date/confirm/${enc(order)}/accept`), null, null] : fail('No order selected.');
case 'request_date': {
    const wanted = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(p.requested_date || '') ? p.requested_date : null;
    if (!order || !customer || !wanted) return fail('Choose the new delivery date.');
    if (new Date(wanted.replace(' ', 'T')) < new Date()) return fail('The new date must be in the future.');
    const previous = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(p.previous_date || '') ? p.previous_date : null;
    // one open request per order
    return [null, sql(`INSERT INTO delivery_change_requests (order_name, customer_id, previous_date, requested_date, reason)
                       SELECT ?, ?, ?, ?, ? FROM DUAL
                       WHERE NOT EXISTS (SELECT 1 FROM delivery_change_requests WHERE order_name = ? AND status = 'pending')`,
        [order, customer, previous, wanted, String(p.reason || '').slice(0, 500) || null, order]), null];
}
case 'requests':
    return customer ? [null, sql(`SELECT request_id, order_name, status, reason, decision_note,
            DATE_FORMAT(previous_date, '%Y-%m-%d %H:%i:%s') AS previous_date,
            DATE_FORMAT(requested_date, '%Y-%m-%d %H:%i:%s') AS requested_date,
            DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS created_at
        FROM delivery_change_requests WHERE customer_id = ? ORDER BY created_at DESC, request_id DESC`, [customer]), null] : null;
case 'send_message': {
    const types = ['question', 'incident', 'complaint', 'suggestion', 'praise'];
    const text = String(p.content || '').trim().slice(0, 1000);
    if (!customer || !text) return fail('Write a message first.');
    return [null, sql(`INSERT INTO user_messages (user_id, message_content, message_type, order_name, message_status, created_at)
                       VALUES (?, ?, ?, ?, 'sent', NOW())`,
        [customer, text, types.includes(p.message_type) ? p.message_type : 'question', order]), null];
}
case 'messages':
    return customer ? [null, sql(`SELECT message_id, message_content, message_type, order_name, message_status, reply_content,
            DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS created_at,
            DATE_FORMAT(replied_at, '%Y-%m-%d %H:%i:%s') AS replied_at
        FROM user_messages WHERE user_id = ? ORDER BY created_at DESC, message_id DESC`, [customer]), null] : null;
default:
    node.warn('Unknown portal action ' + msg.topic);
    return null;
}

// Answer of the integration API. Output 1: to the browser, output 2: follow-up actions
// (refresh the order and the list after a change), output 3: KPI rows for the database.
const a = msg.action, c = msg.ctx || {}, d = msg.payload;
const ui = (topic, payload) => ({ _client: msg._client, topic, payload });
const next = (topic, payload) => ({ _client: msg._client, topic, payload: { customer_id: c.customer_id, ...payload } });
const code = Number(msg.statusCode);
const quiet = ['orders', 'order', 'invoices'].includes(a);   // background reads: no error pop-up for each refresh

if (!code || code >= 400) {
    let detail = d && typeof d === 'object' ? d.detail : null;
    if (Array.isArray(detail)) detail = detail.map(e => e.msg).join('; ');
    const text = !code ? 'The order service cannot be reached. Please try again in a moment.'
                       : (detail || `The request failed (HTTP ${code}).`);
    if (quiet && code) { node.warn(`${a}: ${text}`); return null; }
    return [ui('error', { text }), null, null];
}
const refresh = [next('order', { order_id: c.order_id }), next('orders', {})];

switch (a) {
case 'init':
    return [ui('customers', d), null, null];
case 'login': {
    const profile = Array.isArray(d) ? d[0] : d;
    const me = { customer_id: profile.id };
    return [ui('profile', profile), [next('orders', me), next('messages', me), next('requests', me)], null];
}
case 'orders':
    return [ui('orders', d.map(o => ({ id: o.id, name: o.name, state: o.state, date_order: o.date_order,
        amount_total: o.amount_total, lines: o.order_line.length }))), null, null];
case 'order':
    return [ui('order', d), d.invoice_count ? next('invoices', { order_name: d.name }) : null, null];
case 'invoices':
    return [ui('invoices', { order_name: c.order_name, invoices: d.invoice }), null, null];
case 'confirm':
case 'decline': {
    const done = a === 'confirm';
    return [ui('toast', { text: done ? `${c.order_name} is confirmed. Thank you for your order!` : `${c.order_name} was declined.` }),
            refresh,
            { topic: 'INSERT INTO online_quotes (order_name, customer_id, is_confirmed) VALUES (?, ?, ?)',
              payload: [c.order_name, c.customer_id, done ? 1 : 0], action: 'kpi' }];
}
case 'set_qty':
case 'remove_line':
    return [[ui('order', d), ui('toast', { text: a === 'set_qty' ? 'Quantity updated.' : 'Product removed.' })],
            next('orders', {}), null];
case 'accept_date':
    return [ui('toast', { text: `Thank you, the delivery date of ${c.order_name} is confirmed.` }), null, null];
default:
    return null;
}

// Answer of the MySQL database. Output 1: to the browser, output 2: follow-up actions.
const a = msg.action, c = msg.ctx || {}, d = msg.payload;
const ui = (topic, payload) => ({ _client: msg._client, topic, payload });
const next = topic => ({ _client: msg._client, topic, payload: { customer_id: c.customer_id } });

switch (a) {
case 'login':
    return [ui('visit', { visit_id: d.insertId }), null];
case 'messages':
case 'requests':
    return [ui(a, d), null];
case 'send_message':
    return [ui('toast', { text: c.message_type === 'incident' ? 'Thank you, our team will look into the problem.'
                                                               : 'Message sent. We usually answer within one working day.', reset: true }),
            next('messages')];
case 'request_date':
    if (!d.affectedRows) return [ui('error', { text: `There is already an open request for ${c.order_name}.` }), next('requests')];
    return [ui('toast', { text: 'Request sent. You will see our answer here.' }), next('requests')];
default:
    return null;   // KPI logging, logout
}

// An API call or a query failed before it returned an answer (service down, database not reachable).
const text = /database|ER_|ECONN|mysql/i.test(msg.error && msg.error.message || '')
    ? 'Our database is not reachable at the moment. Please try again later.'
    : 'Something went wrong: ' + ((msg.error && msg.error.message) || 'unknown error');
if (!msg._client) return null;
return { _client: msg._client, topic: 'error', payload: { text } };

const API = env.get('API_URL') || 'http://api:8000';
const id = Number(msg.req.params.id);
const path = { order: '/saleorders/get/pdf/', invoice: '/accounting/invoice/get/pdf/', purchase: '/purchaseorders/get/pdf/' }[msg.req.params.kind];
if (!path || !Number.isInteger(id) || id <= 0) {
    msg.statusCode = 404; msg.payload = 'Unknown document'; msg.headers = { 'Content-Type': 'text/plain' };
    return [null, msg];
}
msg.url = API + path + id; msg.method = 'GET'; msg.payload = ''; msg.headers = {};
msg.filename = `${msg.req.params.kind}_${id}.pdf`;
return [msg, null];

if (msg.statusCode === 200) {
    msg.headers = { 'Content-Type': 'application/pdf', 'Content-Disposition': `inline; filename="${msg.filename}"` };
} else {
    let detail = 'The document is not available.';
    try { detail = JSON.parse(msg.payload.toString()).detail || detail; } catch (e) {}
    msg.statusCode = Number(msg.statusCode) || 503;
    msg.payload = detail; msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
}
return msg;

// Service desk (employees): messages and delivery date requests.
// Output 1: API call, output 2: database query.
const API = env.get('API_URL') || 'http://api:8000';
const p = msg.payload || {};
const base = { _client: msg._client, action: msg.topic, ctx: p };
const sql = (query, params) => ({ ...base, topic: query, payload: params || [] });
const id = v => { const n = Number(v); return Number.isInteger(n) && n > 0 ? n : null; };
const messages = sql(`SELECT message_id, user_id, message_content, message_type, order_name, reply_content,
        DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS created_at, DATE_FORMAT(replied_at, '%Y-%m-%d %H:%i:%s') AS replied_at
    FROM user_messages ORDER BY (reply_content IS NULL) DESC, created_at DESC LIMIT 300`);
messages.action = 'messages';
const requests = sql(`SELECT request_id, order_name, customer_id, status, reason, decision_note,
        DATE_FORMAT(previous_date, '%Y-%m-%d %H:%i:%s') AS previous_date,
        DATE_FORMAT(requested_date, '%Y-%m-%d %H:%i:%s') AS requested_date,
        DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS created_at
    FROM delivery_change_requests ORDER BY (status = 'pending') DESC, created_at DESC LIMIT 200`);
requests.action = 'requests';

switch (msg.topic) {
case 'init':
    return [{ ...base, method: 'GET', url: API + '/customers/all', payload: '', headers: {} }, [messages, requests]];
case 'refresh':
    return [null, [messages, requests]];
case 'reply': {
    const text = String(p.text || '').trim().slice(0, 2000);
    if (!id(p.message_id) || !text) return null;
    return [null, sql(`UPDATE user_messages SET reply_content = ?, replied_at = NOW(), message_status = 'replied'
                       WHERE message_id = ?`, [text, id(p.message_id)])];
}
case 'approve':
    // the requested date becomes the commitment date of the order in Odoo, then the request is closed
    if (!id(p.request_id) || !/^[\w\/-]{1,30}$/.test(p.order_name || '')) return null;
    return [{ ...base, method: 'PUT', payload: '', headers: {},
              url: `${API}/saleorders/delivery_date/confirm/${encodeURIComponent(p.order_name)}/reject/${encodeURIComponent(p.requested_date)}` }, null];
case 'reject':
    if (!id(p.request_id)) return null;
    return [null, sql(`UPDATE delivery_change_requests SET status = 'rejected', decided_at = NOW(), decision_note = ?
                       WHERE request_id = ? AND status = 'pending'`, [String(p.note || '').slice(0, 500) || null, id(p.request_id)])];
}
return null;

// Output 1: to the browser, output 2: database update.
const a = msg.action, c = msg.ctx || {}, d = msg.payload;
const ui = (topic, payload) => ({ _client: msg._client, topic, payload });
const code = Number(msg.statusCode);
if (!code || code >= 400) {
    const detail = d && typeof d === 'object' && typeof d.detail === 'string' ? d.detail : `HTTP ${code || 'no answer'}`;
    return [ui('error', { text: `Odoo was not updated: ${detail}` }), null];
}
if (a === 'init') return [ui('customers', d), null];
if (a === 'approve') {
    return [null, { _client: msg._client, action: 'approve', ctx: c,
        topic: `UPDATE delivery_change_requests SET status = 'approved', decided_at = NOW(), decision_note = ?
                WHERE request_id = ? AND status = 'pending'`,
        payload: [String(c.note || '').slice(0, 500) || null, c.request_id] }];
}
return null;

// Output 1: to the browser, output 2: reload the lists after a change.
const a = msg.action, c = msg.ctx || {};
const ui = (topic, payload) => ({ _client: msg._client, topic, payload });
const refresh = { _client: msg._client, topic: 'refresh', payload: {} };
switch (a) {
case 'messages':
case 'requests':
    return [ui(a, msg.payload), null];
case 'reply':
    return [ui('toast', { text: 'Reply sent to the customer.' }), refresh];
case 'approve':
    return [ui('toast', { text: `${c.order_name}: new delivery date saved in Odoo.` }), refresh];
case 'reject':
    return [ui('toast', { text: `${c.order_name}: request rejected.` }), refresh];
}
return null;

// An API call or a query failed before it returned an answer (service down, database not reachable).
const text = /database|ER_|ECONN|mysql/i.test(msg.error && msg.error.message || '')
    ? 'Our database is not reachable at the moment. Please try again later.'
    : 'Something went wrong: ' + ((msg.error && msg.error.message) || 'unknown error');
if (!msg._client) return null;
return { _client: msg._client, topic: 'error', payload: { text } };

// Back office (employees): every click becomes a call to the integration API.
const API = env.get('API_URL') || 'http://api:8000';
const p = msg.payload || {};
const id = v => { const n = Number(v); return Number.isInteger(n) && n > 0 ? n : null; };
const name = typeof p.order_name === 'string' && /^[\w\/-]{1,30}$/.test(p.order_name) ? encodeURIComponent(p.order_name) : null;
const call = (method, path) => ({ _client: msg._client, action: msg.topic, ctx: p, method, url: API + path, payload: '', headers: {} });

const routes = {
    init:            () => [call('GET', '/customers/all'), call('GET', '/vendors/all')],
    orders:          () => id(p.customer_id) && call('GET', `/saleorders/by_id/${id(p.customer_id)}`),
    order:           () => id(p.order_id) && call('GET', `/saleorders/by_orderid/${id(p.order_id)}`),
    invoices:        () => name && call('GET', `/accounting/invoice/by_saleorder/${name}`),
    confirm:         () => name && call('PUT', `/saleorders/quotations/confirm/${name}`),
    cancel:          () => name && call('PUT', `/saleorders/quotations/cancel/${name}`),
    deliver:         () => name && call('POST', `/saleorders/delivery/validate/${name}`),
    invoice:         () => name && call('POST', `/saleorders/invoice/create/${name}`),
    invoice_confirm: () => id(p.invoice_id) && call('POST', `/accounting/invoice/${id(p.invoice_id)}/confirm`),
    invoice_pay:     () => id(p.invoice_id) && call('POST', `/accounting/invoice/${id(p.invoice_id)}/pay`),
    purchases:       () => id(p.vendor_id) && call('GET', `/purchaseorders/by_vendor_id/${id(p.vendor_id)}`),
    purchase:        () => id(p.po_id) && call('GET', `/purchaseorders/by_id/${id(p.po_id)}`),
    po_confirm:      () => id(p.po_id) && call('PUT', `/purchaseorders/confirm/${id(p.po_id)}`),
    po_cancel:       () => id(p.po_id) && call('PUT', `/purchaseorders/cancel/${id(p.po_id)}`),
    po_arrival:      () => id(p.po_id) && call('PUT', `/purchaseorders/deliverdate/confirm/${id(p.po_id)}`),
};
const route = routes[msg.topic];
const out = route && route();
if (!out) {
    return [null, { _client: msg._client, topic: 'error', payload: { text: 'This action needs a selected order.' } }];
}
return [out, null];

// Answer of the API. Output 1: to the page, output 2: follow-up reads (reload what changed).
const a = msg.action, c = msg.ctx || {}, d = msg.payload;
const ui = (topic, payload) => ({ _client: msg._client, topic, payload });
const next = (topic, payload) => ({ _client: msg._client, topic, payload: { ...c, ...payload } });
const code = Number(msg.statusCode);
if (!code || code >= 400) {
    let detail = d && typeof d === 'object' ? d.detail : null;
    if (Array.isArray(detail)) detail = detail.map(e => e.msg).join('; ');
    return [ui('error', { text: !code ? 'The integration API cannot be reached.' : (detail || `HTTP ${code}`) }), null];
}
const reloadSale = [next('order', {}), next('orders', {})];
const reloadPurchase = [next('purchase', {}), next('purchases', {})];
const done = text => ui('toast', { text });

switch (a) {
case 'init':
    return [ui(msg.url.endsWith('/vendors/all') ? 'vendors' : 'customers', d), null];
case 'orders':
    return [ui('orders', { customer_id: c.customer_id, orders: d.map(o => ({ id: o.id, name: o.name, state: o.state,
        date_order: o.date_order, amount_total: o.amount_total, invoice_status: o.invoice_status })) }), null];
case 'order':
    return [ui('order', d), next('invoices', { order_name: d.name })];
case 'invoices':
    return [ui('invoices', { order_name: c.order_name, invoices: d.invoice }), null];
case 'confirm':  return [done(`${c.order_name} confirmed: it is now a sales order and a delivery was created.`), reloadSale];
case 'cancel':   return [done(`${c.order_name} cancelled.`), reloadSale];
case 'deliver':  return [done(`${c.order_name} delivered.`), reloadSale];
case 'invoice':  return [done(`Draft invoice created for ${c.order_name}. Confirm it to send it.`), reloadSale];
case 'invoice_confirm': return [done(d.message), reloadSale];
case 'invoice_pay':     return [done(d.message), reloadSale];
case 'purchases':
    return [ui('purchases', { vendor_id: c.vendor_id, orders: d.map(o => ({ id: o.id, name: o.name, state: o.state,
        date_order: o.date_order, amount_total: o.amount_total })) }), null];
case 'purchase':
    return [ui('purchase', d), null];
case 'po_confirm': return [done(`${c.po_name} confirmed and sent to the vendor.`), reloadPurchase];
case 'po_cancel':  return [done(`${c.po_name} cancelled.`), reloadPurchase];
case 'po_arrival': return [done(`Arrival date of ${c.po_name} marked as confirmed by the vendor.`), reloadPurchase];
}
return null;

// An API call or a query failed before it returned an answer (service down, database not reachable).
const text = /database|ER_|ECONN|mysql/i.test(msg.error && msg.error.message || '')
    ? 'Our database is not reachable at the moment. Please try again later.'
    : 'Something went wrong: ' + ((msg.error && msg.error.message) || 'unknown error');
if (!msg._client) return null;
return { _client: msg._client, topic: 'error', payload: { text } };
